/**
 * Bundled example session for trying dicompare without DICOMs of your own.
 *
 * A synthetic, anonymized session (a T1w MPRAGE and a multi-echo GRE for QSM),
 * generated by scripts/example-data/generate_example_data.py. It is served as
 * one zip from public/, so it goes through the same upload path as a zip the
 * user drops (processUploadedFiles extracts it).
 */

import { filesToFileList } from './workspaceHelpers';

export const EXAMPLE_DATA_FILENAME = 'dicompare-example-session.zip';

/** Relative to the app's base, so it works under /, /dicompare-web/ and file:// (Electron). */
export function exampleDataUrl(): string {
  return `${import.meta.env.BASE_URL}example-data/${EXAMPLE_DATA_FILENAME}`;
}

/** Fetch the example session as a FileList, ready for the normal upload handlers. */
export async function fetchExampleDataFiles(): Promise<FileList> {
  const response = await fetch(exampleDataUrl());
  if (!response.ok) {
    throw new Error(`Could not load example data (HTTP ${response.status})`);
  }
  const blob = await response.blob();
  const file = new File([blob], EXAMPLE_DATA_FILENAME, { type: 'application/zip' });
  return filesToFileList([file]);
}
